<template><div class="page-container"><PageHeader>预警管理</PageHeader><el-alert title="预警阈值 = 安全库存 + 覆盖采购周期所需的预计消耗量；生命周期临近采购周期或 7 天时同样预警。" type="info" :closable="false" style="margin-bottom:16px"/><el-table v-loading="loading" :data="rows" border stripe><el-table-column label="类型" width="120"><template #default="{row}"><el-tag :type="row.alertType==='STOCK'?'danger':'warning'">{{row.alertType==='STOCK'?'库存不足':'生命周期临期'}}</el-tag></template></el-table-column><el-table-column prop="equipmentCode" label="设备"/><el-table-column prop="sku" label="SKU"/><el-table-column prop="productName" label="备件"/><el-table-column prop="stockQty" label="当前库存"/><el-table-column prop="reorderPoint" label="补货点"/><el-table-column prop="procurementLeadDays" label="采购周期(天)"/><el-table-column prop="nextExpectedUseDate" label="预计下次领用"/></el-table><el-empty v-if="!loading&&!rows.length" description="暂无预警"/></div></template><script setup>import{ref,onMounted}from'vue';import PageHeader from '@/components/PageHeader.vue';import{alerts}from '@/api/equipment';const rows=ref([]),loading=ref(false);async function load(){loading.value=true;try{rows.value=await alerts()}finally{loading.value=false}}onMounted(load)</script>
